function c(t){try{const n=new URL(t);if(!n.hostname.endsWith("github.com"))return null;const e=n.pathname.split("/").filter(Boolean);if(e.length<4||e[2]!=="pull")return null;const o=parseInt(e[3],10);return isNaN(o)||o<=0?null:{owner:e[0],repo:e[1],pullNumber:o}}catch{return null}}function s(t){const n={type:"PR_CONTEXT_RESULT",payload:t};chrome.runtime.sendMessage(n).catch(()=>{})}function i(){const t=c(window.location.href);t&&s(t)}i();let r=window.location.href;const u=new MutationObserver(()=>{const t=window.location.href;t!==r&&(r=t,i())}),l=document.querySelector("title");l&&u.observe(l,{childList:!0});window.addEventListener("popstate",()=>{const t=window.location.href;t!==r&&(r=t,i())});export{c as e};
